-- GovAI — Tłumaczenia treści katalogowych (ai_act_requirements, app_settings, providers)
--
-- PLIK GENEROWANY — NIE EDYTUJ RĘCZNIE. Źródło: db/i18n/<locale>/*.json,
-- generator: node scripts/gen-db-i18n.mjs
--
-- Kolumna bazowa (polski) nie jest zmieniana; uzupełniane są kolumny *_i18n.
-- Tłumaczenia już zapisane w bazie (np. poprawione w UI) wygrywają; pliki uzupełniają brakujące języki.
-- Idempotentna — deploy-remote.sh uruchamia wszystkie migracje przy każdym deployu.

-- ── ai_act_requirements ───────────────────────────────────────────────────
UPDATE ai_act_requirements SET title_i18n = '{"en":"Data and data governance","de":"Daten und Daten-Governance","it":"Dati e governance dei dati","es":"Datos y gobernanza de datos","fr":"Données et gouvernance des données","ro":"Cerințe privind datele","ru":"Данные и управление данными","sl":"Zahteve glede podatkov","hr":"Podaci i upravljanje podacima"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"Training, validation and testing data sets must meet quality criteria — relevance, representativeness, freedom from errors and completeness. Documentation of the data sets is required.","de":"Trainings-, Validierungs- und Testdatensätze müssen Qualitätskriterien erfüllen — Relevanz, Repräsentativität, Fehlerfreiheit und Vollständigkeit. Eine Dokumentation der Datensätze ist erforderlich.","it":"I set di dati di addestramento, convalida e prova devono soddisfare criteri di qualità: pertinenza, rappresentatività, assenza di errori e completezza. È richiesta la documentazione dei set di dati.","es":"Los conjuntos de datos de entrenamiento, validación y prueba deben cumplir criterios de calidad: pertinencia, representatividad, ausencia de errores e integridad. Se requiere documentar los conjuntos de datos.","fr":"Les jeux de données d’entraînement, de validation et de test doivent satisfaire à des critères de qualité — pertinence, représentativité, absence d’erreurs et exhaustivité. Une documentation des jeux de données est requise.","ro":"Seturile de date de antrenament, de validare și de testare trebuie să îndeplinească criterii de calitate — relevanță, reprezentativitate, lipsa erorilor și completitudine. Este necesară documentarea seturilor de date.","ru":"Обучающие, валидационные и тестовые наборы данных должны соответствовать критериям качества — релевантность, репрезентативность, отсутствие ошибок и полнота. Требуется документирование наборов данных.","sl":"Učni, validacijski in testni podatki morajo izpolnjevati merila kakovosti — ustreznost, reprezentativnost, brez napak in popolnost. Zahtevana je dokumentacija podatkovnih nizov.","hr":"Skupovi podataka za treniranje, validaciju i testiranje moraju ispunjavati kriterije kvalitete — relevantnost, reprezentativnost, odsutnost pogrešaka i potpunost. Potrebna je dokumentacija skupova podataka."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 10';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Technical documentation","de":"Technische Dokumentation","it":"Documentazione tecnica","es":"Documentación técnica","fr":"Documentation technique","ro":"Documentația tehnică","ru":"Техническая документация","sl":"Tehnična dokumentacija","hr":"Tehnička dokumentacija"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"Complete technical documentation in accordance with Annex IV to the EU AI Act is required before the system is placed on the market or put into service. The documentation must be kept up to date throughout the system''s lifecycle.","de":"Vor dem Inverkehrbringen bzw. der Inbetriebnahme ist eine vollständige technische Dokumentation gemäß Anhang IV EU AI Act erforderlich. Das Dokument muss während des gesamten Lebenszyklus des Systems auf dem neuesten Stand gehalten werden.","it":"Prima della messa in servizio è richiesta una documentazione tecnica completa conforme all''allegato IV dell''EU AI Act. Il documento deve essere tenuto aggiornato per l''intero ciclo di vita del sistema.","es":"Antes de su introducción en el mercado o puesta en servicio se requiere una documentación técnica completa conforme al anexo IV del EU AI Act. El documento debe mantenerse actualizado durante todo el ciclo de vida del sistema.","fr":"Avant la mise en service, une documentation technique complète conforme à l’annexe IV de l’EU AI Act est requise. Ce document doit être tenu à jour tout au long du cycle de vie du système.","ro":"Înainte de punerea în funcțiune este necesară o documentație tehnică completă, conformă cu anexa IV la EU AI Act. Documentația trebuie actualizată pe întreaga durată a ciclului de viață al sistemului.","ru":"До ввода в эксплуатацию требуется полная техническая документация в соответствии с Приложением IV EU AI Act. Документ должен актуализироваться на протяжении всего жизненного цикла системы.","sl":"Pred dajanjem v uporabo je zahtevana popolna tehnična dokumentacija v skladu s Prilogo IV EU AI Act. Dokument je treba posodabljati ves življenjski cikel sistema.","hr":"Prije stavljanja u upotrebu potrebna je potpuna tehnička dokumentacija u skladu s Prilogom IV. EU AI Acta. Dokumentacija se mora ažurirati tijekom cijelog životnog ciklusa sustava."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 11';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Transparency and provision of information","de":"Transparenz und Bereitstellung von Informationen","it":"Trasparenza e fornitura di informazioni","es":"Transparencia y comunicación de información","fr":"Transparence et fourniture d’informations","ro":"Transparență și furnizarea de informații","ru":"Прозрачность и предоставление информации","sl":"Preglednost in zagotavljanje informacij","hr":"Transparentnost i pružanje informacija"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The AI system must ensure operational transparency. Users must be informed that they are interacting with an AI system and understand how it works to the extent necessary for oversight.","de":"Das KI-System muss betriebliche Transparenz gewährleisten. Nutzer müssen über die Interaktion mit einem KI-System informiert werden und seine Funktionsweise in dem für die Aufsicht erforderlichen Maß verstehen.","it":"Il sistema di IA deve garantire la trasparenza del funzionamento. Gli utenti devono essere informati dell''interazione con un sistema di IA e comprenderne il funzionamento nella misura necessaria alla sorveglianza.","es":"El sistema de IA debe garantizar la transparencia de su funcionamiento. Los usuarios deben ser informados de que interactúan con un sistema de IA y comprender su funcionamiento en la medida necesaria para la supervisión.","fr":"Le système d’IA doit garantir un fonctionnement suffisamment transparent. Les utilisateurs doivent être informés qu’ils interagissent avec un système d’IA et en comprendre le fonctionnement dans la mesure nécessaire au contrôle.","ro":"Sistemul de IA trebuie să asigure transparența funcționării. Utilizatorii trebuie informați cu privire la interacțiunea cu un sistem de IA și trebuie să înțeleagă funcționarea acestuia în măsura necesară supravegherii.","ru":"Система ИИ должна обеспечивать прозрачность функционирования. Пользователи должны быть проинформированы о взаимодействии с системой ИИ и понимать принцип её работы в объёме, необходимом для надзора.","sl":"Sistem UI mora zagotavljati preglednost delovanja. Uporabniki morajo biti obveščeni o interakciji s sistemom UI in razumeti njegovo delovanje v obsegu, potrebnem za nadzor.","hr":"UI sustav mora osigurati operativnu transparentnost. Korisnici moraju biti obaviješteni o interakciji s UI sustavom i razumjeti njegov rad u mjeri potrebnoj za nadzor."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 13';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Human oversight","de":"Menschliche Aufsicht","it":"Sorveglianza umana","es":"Supervisión humana","fr":"Contrôle humain","ro":"Supravegherea umană","ru":"Человеческий надзор","sl":"Človeški nadzor","hr":"Ljudski nadzor"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"Measures are in place enabling natural persons to understand, monitor and intervene in the operation of the AI system. It must be possible to stop or reverse any decision made by the system.","de":"Es sind Maßnahmen umgesetzt, die es einem Menschen ermöglichen, die Funktionsweise des KI-Systems zu verstehen, zu überwachen und in sie einzugreifen. Jede Entscheidung des Systems kann angehalten oder rückgängig gemacht werden.","it":"Misure attuate che consentono alle persone fisiche di comprendere, monitorare e intervenire sul funzionamento del sistema di IA. Possibilità di arrestare o annullare qualsiasi decisione del sistema.","es":"Medidas implantadas que permitan a una persona física comprender, vigilar e intervenir en el funcionamiento del sistema de IA. Posibilidad de detener o revertir cualquier decisión del sistema.","fr":"Des mesures permettant à une personne physique de comprendre, de surveiller et d’intervenir dans le fonctionnement du système d’IA sont mises en œuvre. Toute décision du système doit pouvoir être interrompue ou annulée.","ro":"Măsuri implementate care permit persoanelor fizice să înțeleagă, să monitorizeze și să intervină în funcționarea sistemului de IA. Posibilitatea de a opri sau de a inversa orice decizie a sistemului.","ru":"Внедрены меры, позволяющие человеку понимать и отслеживать работу системы ИИ и вмешиваться в неё. Обеспечена возможность остановить или отменить любое решение системы.","sl":"Uvedeni ukrepi, ki človeku omogočajo razumevanje, spremljanje in posredovanje v delovanje sistema UI. Možnost ustavitve ali razveljavitve vsake odločitve sistema.","hr":"Uvedene mjere koje čovjeku omogućuju razumijevanje i praćenje rada UI sustava te intervenciju u njegov rad. Mogućnost zaustavljanja ili poništavanja svake odluke sustava."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 14';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Accuracy and robustness","de":"Genauigkeit und Robustheit","it":"Accuratezza e robustezza","es":"Precisión, solidez y ciberseguridad","fr":"Exactitude et robustesse","ro":"Acuratețe și robustețe","ru":"Точность и устойчивость","sl":"Točnost in robustnost","hr":"Točnost i otpornost"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The system must achieve an appropriate level of accuracy throughout its lifecycle. Testing of resilience to errors, attacks and unexpected inputs is required.","de":"Das System muss während seines gesamten Lebenszyklus ein angemessenes Maß an Genauigkeit erreichen. Erforderlich sind Tests der Robustheit gegenüber Fehlern, Angriffen und unerwarteten Eingabedaten.","it":"Il sistema deve conseguire un adeguato livello di accuratezza per l''intero ciclo di vita. Sono richiesti test di robustezza rispetto a errori, attacchi e dati di input imprevisti.","es":"El sistema debe alcanzar un nivel adecuado de precisión durante todo su ciclo de vida. Se requieren pruebas de solidez frente a errores, ataques y datos de entrada inesperados.","fr":"Le système doit atteindre un niveau d’exactitude approprié tout au long de son cycle de vie. Des tests de robustesse face aux erreurs, aux attaques et aux données d’entrée inattendues sont requis.","ro":"Sistemul trebuie să atingă un nivel adecvat de acuratețe pe întreaga durată a ciclului de viață. Sunt necesare teste de reziliență la erori, atacuri și date de intrare neprevăzute.","ru":"Система должна достигать надлежащего уровня точности на протяжении всего жизненного цикла. Требуются испытания на устойчивость к ошибкам, атакам и непредвиденным входным данным.","sl":"Sistem mora ves življenjski cikel dosegati ustrezno raven točnosti. Zahtevani so testi odpornosti na napake, napade in nepričakovane vhodne podatke.","hr":"Sustav mora postizati odgovarajuću razinu točnosti tijekom cijelog životnog ciklusa. Potrebna su testiranja otpornosti na pogreške, napade i neočekivane ulazne podatke."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 15';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Quality management system","de":"Qualitätsmanagementsystem","it":"Sistema di gestione della qualità","es":"Sistema de gestión de la calidad","fr":"Système de gestion de la qualité","ro":"Sistemul de management al calității","ru":"Система управления качеством","sl":"Sistem upravljanja kakovosti","hr":"Sustav upravljanja kvalitetom"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The provider puts in place a quality management system comprising policies, procedures and instructions to ensure compliance with the EU AI Act.","de":"Der Anbieter richtet ein Qualitätsmanagementsystem ein, das Konzepte, Verfahren und Anweisungen zur Gewährleistung der Konformität mit dem EU AI Act umfasst.","it":"Il fornitore istituisce un sistema di gestione della qualità che comprende politiche, procedure e istruzioni volte a garantire la conformità all''EU AI Act.","es":"El proveedor establece un sistema de gestión de la calidad que incluya políticas, procedimientos e instrucciones para garantizar el cumplimiento del EU AI Act.","fr":"Le fournisseur met en place un système de gestion de la qualité comprenant des politiques, des procédures et des instructions visant à garantir la conformité à l’EU AI Act.","ro":"Furnizorul instituie un sistem de management al calității care cuprinde politici, proceduri și instrucțiuni pentru asigurarea conformității cu EU AI Act.","ru":"Поставщик внедряет систему управления качеством, включающую политики, процедуры и инструкции для обеспечения соответствия EU AI Act.","sl":"Ponudnik vzpostavi sistem upravljanja kakovosti, ki zajema politike, postopke in navodila za zagotavljanje skladnosti z EU AI Act.","hr":"Dobavljač uspostavlja sustav upravljanja kvalitetom koji obuhvaća politike, postupke i upute kojima se osigurava usklađenost s EU AI Actom."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 17';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Human oversight assigned to a competent person","de":"Übertragung der menschlichen Aufsicht an kompetente Personen","it":"Sorveglianza umana affidata a una persona competente","es":"Supervisión humana encomendada a una persona competente","fr":"Contrôle humain confié à une personne compétente","ro":"Supraveghere umană încredințată unei persoane competente","ru":"Человеческий надзор, порученный компетентному лицу","sl":"Človeški nadzor, dodeljen usposobljeni osebi","hr":"Ljudski nadzor povjeren kompetentnoj osobi"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The deployer of a high-risk AI system must assign human oversight to natural persons who have the necessary competence, training and authority, as well as the necessary support.","de":"Der Betreiber eines Hochrisiko-KI-Systems muss die menschliche Aufsicht natürlichen Personen übertragen, die über die erforderliche Kompetenz, Ausbildung und Befugnis verfügen und die nötige Unterstützung erhalten.","it":"Il deployer di un sistema ad alto rischio deve affidare la sorveglianza umana a persone fisiche che dispongono della competenza, della formazione, dell''autorità e del sostegno necessari.","es":"El responsable del despliegue de un sistema de alto riesgo debe encomendar la supervisión humana a personas físicas que tengan la competencia, la formación y la autoridad necesarias, así como el apoyo necesario para ejercerla.","fr":"Le déployeur d’un système à haut risque doit confier le contrôle humain à des personnes physiques disposant des compétences, de la formation, de l’autorité et du soutien nécessaires pour l’exercer.","ro":"Implementatorul unui sistem cu grad ridicat de risc trebuie să încredințeze supravegherea umană unor persoane fizice care dispun de competența, formarea, autoritatea și sprijinul necesare pentru exercitarea acesteia.","ru":"Эксплуатант системы высокого риска должен поручить человеческий надзор лицам, обладающим необходимой компетенцией, подготовкой, полномочиями и поддержкой для его осуществления.","sl":"Uvajalec visokotveganega sistema UI mora človeški nadzor dodeliti osebam, ki imajo potrebne kompetence, usposabljanje, pooblastila in podporo za njegovo izvajanje.","hr":"Subjekt koji uvodi visokorizični UI sustav mora ljudski nadzor povjeriti fizičkim osobama koje imaju potrebne kompetencije, osposobljenost i ovlasti te potrebnu potporu za njegovo provođenje."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 26 ust. 2';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Monitoring of operation and informing the provider","de":"Überwachung des Betriebs und Information des Anbieters","it":"Monitoraggio del funzionamento e informazione del fornitore","es":"Vigilancia del funcionamiento e información al proveedor","fr":"Surveillance du fonctionnement et information du fournisseur","ro":"Monitorizarea funcționării și informarea furnizorului","ru":"Мониторинг функционирования и информирование поставщика","sl":"Spremljanje delovanja in obveščanje ponudnika","hr":"Praćenje rada i obavješćivanje dobavljača"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The deployer must monitor the operation of the system on the basis of the instructions for use and inform the provider and, where relevant, the market surveillance authority of any identified risk or serious incident.","de":"Der Betreiber muss den Betrieb des Systems anhand der Betriebsanleitung überwachen und den Anbieter sowie — falls zutreffend — die Marktüberwachungsbehörde über ein festgestelltes Risiko oder einen schwerwiegenden Vorfall informieren.","it":"Il deployer deve monitorare il funzionamento del sistema sulla base delle istruzioni per l''uso e informare il fornitore e, se del caso, l''autorità di vigilanza del mercato di un rischio individuato o di un incidente grave.","es":"El responsable del despliegue debe vigilar el funcionamiento del sistema conforme a las instrucciones de uso e informar al proveedor y, en su caso, a la autoridad de vigilancia del mercado de cualquier riesgo detectado o incidente grave.","fr":"Le déployeur doit surveiller le fonctionnement du système conformément à la notice d’utilisation et informer le fournisseur ainsi que, le cas échéant, l’autorité de surveillance du marché de tout risque identifié ou de tout incident grave.","ro":"Implementatorul trebuie să monitorizeze funcționarea sistemului pe baza instrucțiunilor de utilizare și să informeze furnizorul și — după caz — autoritatea de supraveghere a pieței cu privire la riscurile identificate sau la incidentele grave.","ru":"Эксплуатант должен отслеживать функционирование системы в соответствии с инструкцией по эксплуатации и информировать поставщика, а также — в применимых случаях — орган надзора за рынком о выявленном риске или серьёзном инциденте.","sl":"Uvajalec mora spremljati delovanje sistema v skladu z navodili za uporabo ter obveščati ponudnika in — kadar je ustrezno — organ za nadzor trga o ugotovljenem tveganju ali resnem incidentu.","hr":"Subjekt koji uvodi sustav mora pratiti rad sustava u skladu s uputama za upotrebu te obavijestiti dobavljača i — ako je primjenjivo — tijelo za nadzor tržišta o utvrđenom riziku ili ozbiljnom incidentu."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 26 ust. 5';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Retention of automatically generated logs","de":"Aufbewahrung automatisch erzeugter Protokolle","it":"Conservazione dei log generati automaticamente","es":"Conservación de los archivos de registro automáticos","fr":"Conservation des journaux générés automatiquement","ro":"Păstrarea jurnalelor generate automat","ru":"Хранение автоматически генерируемых журналов","sl":"Hramba samodejno ustvarjenih dnevniških zapisov","hr":"Čuvanje automatski generiranih zapisa"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The deployer must keep the logs automatically generated by the system for a period appropriate to the intended purpose of the system, of at least six months, unless provided otherwise in applicable Union or national law.","de":"Der Betreiber muss die automatisch erzeugten Protokolle des Systems für einen der Zweckbestimmung des Systems angemessenen Zeitraum von mindestens sechs Monaten aufbewahren, sofern im Unionsrecht oder im nationalen Recht nichts anderes bestimmt ist.","it":"Il deployer deve conservare i log generati automaticamente dal sistema per un periodo adeguato alla finalità prevista del sistema, pari ad almeno sei mesi, salvo diversamente disposto dal diritto dell''Unione o nazionale.","es":"El responsable del despliegue debe conservar los archivos de registro generados automáticamente por el sistema durante un período adecuado a la finalidad prevista del sistema, de al menos seis meses, salvo que el Derecho de la Unión o nacional disponga otra cosa.","fr":"Le déployeur doit conserver les journaux générés automatiquement par le système pendant une période adaptée à la destination du système, d’au moins six mois, sauf disposition contraire du droit de l’Union ou du droit national.","ro":"Implementatorul trebuie să păstreze jurnalele generate automat de sistem pentru o perioadă adecvată scopului preconizat al sistemului, de cel puțin șase luni, cu excepția cazului în care dreptul Uniunii sau dreptul intern prevede altfel.","ru":"Эксплуатант должен хранить автоматически генерируемые журналы системы в течение срока, соответствующего назначению системы, но не менее 6 месяцев, если иное не предусмотрено правом ЕС или национальным правом.","sl":"Uvajalec mora samodejno ustvarjene dnevniške zapise sistema hraniti obdobje, ki ustreza namenu sistema, in sicer najmanj 6 mesecev, razen če pravo Unije ali nacionalno pravo ne določa drugače.","hr":"Subjekt koji uvodi sustav mora čuvati automatski generirane zapise sustava tijekom razdoblja primjerenog namjeni sustava, a najmanje šest mjeseci, osim ako je pravom Unije ili nacionalnim pravom propisano drukčije."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 26 ust. 6';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Verification of registration in the EU database","de":"Überprüfung der Registrierung in der EU-Datenbank","it":"Verifica della registrazione nella banca dati dell''UE","es":"Verificación del registro en la base de datos de la UE","fr":"Vérification de l’enregistrement dans la base de données de l’UE","ro":"Verificarea înregistrării în baza de date a UE","ru":"Проверка регистрации в базе данных ЕС","sl":"Preverjanje registracije v podatkovni zbirki EU","hr":"Provjera registracije u bazi podataka EU-a"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"A deployer that is a public authority must comply with the registration obligations referred to in Art. 49 and, before putting the system into service, verify that it is registered in the EU database.","de":"Betreiber, die Behörden oder öffentliche Stellen sind, müssen die Registrierungspflichten nach Art. 49 erfüllen und vor der Inbetriebnahme des Systems überprüfen, ob es in der EU-Datenbank registriert ist.","it":"Il deployer che è un''autorità pubblica deve rispettare gli obblighi di registrazione di cui all''art. 49 e, prima di mettere in uso il sistema, verificare che sia registrato nella banca dati dell''UE.","es":"El responsable del despliegue que sea una autoridad pública debe cumplir las obligaciones de registro del art. 49 y, antes de poner en servicio el sistema, verificar que está registrado en la base de datos de la UE.","fr":"Le déployeur qui est une autorité publique doit respecter les obligations d’enregistrement prévues à l’art. 49 et, avant la mise en service du système, vérifier que celui-ci est enregistré dans la base de données de l’UE.","ro":"Implementatorul care este autoritate publică trebuie să respecte obligațiile de înregistrare prevăzute la art. 49 și, înainte de punerea în funcțiune a sistemului, să verifice dacă acesta este înregistrat în baza de date a UE.","ru":"Эксплуатант, являющийся публичным органом, должен соблюдать обязанности по регистрации согласно ст. 49 и до ввода системы в эксплуатацию убедиться, что она зарегистрирована в базе данных ЕС.","sl":"Uvajalec, ki je javni organ, mora izpolnjevati obveznosti registracije iz člena 49 in pred začetkom uporabe sistema preveriti, ali je ta registriran v podatkovni zbirki EU.","hr":"Subjekt koji uvodi sustav, a koji je tijelo javne vlasti, mora ispunjavati obveze registracije iz članka 49. te prije stavljanja sustava u upotrebu provjeriti je li sustav registriran u bazi podataka EU-a."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 26 ust. 8';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Fundamental rights impact assessment (FRIA)","de":"Grundrechte-Folgenabschätzung (FRIA)","it":"Valutazione d''impatto sui diritti fondamentali (FRIA)","es":"Evaluación de impacto relativa a los derechos fundamentales (FRIA)","fr":"Analyse d’impact sur les droits fondamentaux (FRIA)","ro":"Evaluarea impactului asupra drepturilor fundamentale (FRIA)","ru":"Оценка воздействия на основные права (FRIA)","sl":"Ocena učinka na temeljne pravice (FRIA)","hr":"Procjena učinka na temeljna prava (FRIA)"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"Before deploying a high-risk AI system referred to in Annex III, point 5(b) or (c) (creditworthiness assessment, insurance risk), or where the deployer is a body governed by public law or a private entity providing public services, the deployer must perform a fundamental rights impact assessment: a description of the processes in which the system will be used, the period and frequency of use, the categories of persons affected, the risks of harm to those persons, and the human oversight measures and complaint mechanisms.","de":"Vor der Inbetriebnahme eines Hochrisiko-KI-Systems gemäß Anhang III Nr. 5 Buchst. b/c (Kreditwürdigkeitsprüfung, Versicherungsrisiko) oder durch eine öffentliche Stelle bzw. eine private Einrichtung, die öffentliche Dienste erbringt, muss der Betreiber eine Grundrechte-Folgenabschätzung durchführen: Beschreibung der Verwendungsprozesse, Zeitraum und Häufigkeit der Verwendung, Kategorien betroffener Personen, Schadensrisiken für diese Personen sowie Maßnahmen der menschlichen Aufsicht und Beschwerdemechanismen.","it":"Prima di utilizzare un sistema ad alto rischio di cui all''allegato III, punto 5, lettere b) e c) (valutazione dell''affidabilità creditizia, rischio assicurativo), o se si tratta di un organismo di diritto pubblico o di un ente privato che fornisce servizi pubblici, il deployer deve effettuare una valutazione d''impatto sui diritti fondamentali: descrizione dei processi di utilizzo, periodo e frequenza di utilizzo, categorie di persone interessate, rischi di danno per tali persone, nonché misure di sorveglianza umana e meccanismi di reclamo.","es":"Antes de desplegar un sistema de alto riesgo contemplado en el anexo III, punto 5, letras b) o c) (evaluación de la solvencia, riesgo en seguros), o cuando se trate de un organismo público o de una entidad privada que preste servicios públicos, el responsable del despliegue debe llevar a cabo una evaluación de impacto relativa a los derechos fundamentales: descripción de los procesos de uso, período y frecuencia de uso, categorías de personas afectadas, riesgos de perjuicio para dichas personas, así como medidas de supervisión humana y mecanismos de reclamación.","fr":"Avant de déployer un système à haut risque visé à l’annexe III, point 5 b) ou c) (évaluation de la solvabilité, risque en matière d’assurance), ou lorsqu’il s’agit d’un organisme de droit public ou d’une entité privée fournissant des services publics, le déployeur doit procéder à une analyse d’impact sur les droits fondamentaux : description des processus d’utilisation, période et fréquence d’utilisation, catégories de personnes concernées, risques de préjudice pour ces personnes, ainsi que mesures de contrôle humain et mécanismes de recours.","ro":"Înainte de implementarea unui sistem cu grad ridicat de risc menționat la anexa III punctul 5 literele (b)/(c) (evaluarea bonității, riscul în asigurări) sau de către o entitate publică/privată care furnizează servicii publice, implementatorul trebuie să efectueze o evaluare a impactului asupra drepturilor fundamentale: descrierea proceselor de utilizare, perioada și frecvența utilizării, categoriile de persoane afectate, riscurile de prejudiciu pentru aceste persoane, precum și măsurile de supraveghere umană și mecanismele de reclamație.","ru":"До ввода в эксплуатацию системы высокого риска, указанной в п. 5(b)/(c) Приложения III (оценка кредитоспособности, страховой риск), либо публичным органом или частной организацией, оказывающей публичные услуги, эксплуатант должен провести оценку воздействия на основные права: описание процессов использования, срок и частота использования, категории затрагиваемых лиц, риски причинения вреда этим лицам, а также меры человеческого надзора и механизмы обжалования.","sl":"Pred uvedbo visokotveganega sistema iz točke 5(b)/(c) Priloge III (ocena kreditne sposobnosti, zavarovalno tveganje) ali kadar sistem uvaja javni subjekt/zasebni subjekt, ki opravlja javne storitve, mora uvajalec izvesti oceno učinka na temeljne pravice: opis postopkov uporabe, obdobje in pogostost uporabe, kategorije prizadetih oseb, tveganja škode za te osebe ter ukrepe človeškega nadzora in pritožbene mehanizme.","hr":"Prije uvođenja visokorizičnog UI sustava iz točke 5. podtočaka (b) i (c) Priloga III. (procjena kreditne sposobnosti, rizik u osiguranju) ili ako je riječ o tijelu javnog prava ili privatnom subjektu koji pruža javne usluge, subjekt koji uvodi sustav mora provesti procjenu učinka na temeljna prava: opis postupaka u kojima se sustav upotrebljava, razdoblje i učestalost upotrebe, kategorije pogođenih osoba, rizike od štete za te osobe te mjere ljudskog nadzora i mehanizme pravne zaštite."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 27';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Conformity assessment","de":"Konformitätsbewertung","it":"Valutazione della conformità","es":"Evaluación de la conformidad","fr":"Évaluation de la conformité","ro":"Evaluarea conformității","ru":"Оценка соответствия","sl":"Ugotavljanje skladnosti","hr":"Ocjenjivanje sukladnosti"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"High-risk AI systems listed in Annex III must undergo a conformity assessment (internal control or involving a notified body) before being placed on the market or put into service.","de":"Hochrisiko-KI-Systeme nach Anhang III erfordern vor dem Inverkehrbringen bzw. der Inbetriebnahme die Durchführung einer Konformitätsbewertung (interne Kontrolle oder durch eine notifizierte Stelle).","it":"I sistemi ad alto rischio di cui all''allegato III richiedono una valutazione della conformità (controllo interno o tramite organismo notificato) prima dell''immissione sul mercato o della messa in servizio.","es":"Los sistemas de alto riesgo del anexo III deben someterse a una evaluación de la conformidad (control interno o por un organismo notificado) antes de su introducción en el mercado o puesta en servicio.","fr":"Les systèmes à haut risque visés à l’annexe III doivent faire l’objet d’une évaluation de la conformité (contrôle interne ou par un organisme notifié) avant leur mise en service.","ro":"Sistemele cu grad ridicat de risc din anexa III necesită efectuarea unei evaluări a conformității (autoevaluare sau de către un organism notificat) înainte de punerea în funcțiune.","ru":"Системы высокого риска из Приложения III требуют проведения оценки соответствия (самооценка или оценка нотифицированным органом) до ввода в эксплуатацию.","sl":"Za visokotvegane sisteme iz Priloge III je pred dajanjem v uporabo treba izvesti ugotavljanje skladnosti (z notranjo kontrolo ali prek priglašenega organa).","hr":"Za visokorizične sustave iz Priloga III. potrebno je prije stavljanja u upotrebu provesti ocjenjivanje sukladnosti (interna kontrola ili uz sudjelovanje prijavljenog tijela)."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 43';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Registration in the EU database","de":"Registrierung in der EU-Datenbank","it":"Registrazione nella banca dati dell''UE","es":"Registro en la base de datos de la UE","fr":"Enregistrement dans la base de données de l’UE","ro":"Înregistrarea în baza de date a UE","ru":"Регистрация в базе данных ЕС","sl":"Registracija v podatkovni zbirki EU","hr":"Registracija u bazi podataka EU-a"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"High-risk AI systems must be registered in the EU database before being placed on the market or put into service.","de":"Hochrisiko-KI-Systeme müssen vor dem Inverkehrbringen bzw. der Inbetriebnahme in der EU-Datenbank registriert werden.","it":"I sistemi ad alto rischio devono essere registrati nella banca dati dell''UE prima dell''immissione sul mercato o della messa in servizio.","es":"Los sistemas de alto riesgo deben estar registrados en la base de datos de la UE antes de su introducción en el mercado o puesta en servicio.","fr":"Les systèmes à haut risque doivent être enregistrés dans la base de données de l’UE avant leur mise en service.","ro":"Sistemele cu grad ridicat de risc trebuie înregistrate în baza de date a UE înainte de punerea în funcțiune.","ru":"Системы высокого риска должны быть зарегистрированы в базе данных ЕС до ввода в эксплуатацию.","sl":"Visokotvegani sistemi morajo biti pred dajanjem v uporabo registrirani v podatkovni zbirki EU za sisteme UI.","hr":"Visokorizični sustavi moraju biti registrirani u bazi podataka EU-a za UI sustave prije stavljanja u upotrebu."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 49';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Risk management system","de":"Risikomanagementsystem","it":"Sistema di gestione dei rischi","es":"Sistema de gestión de riesgos","fr":"Système de gestion des risques","ro":"Sistemul de gestionare a riscurilor","ru":"Система управления рисками","sl":"Sistem obvladovanja tveganja","hr":"Sustav upravljanja rizikom"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"A high-risk agent requires a documented risk management system throughout its entire lifecycle. Identification, analysis and evaluation of risks and the adoption of risk management measures are required.","de":"Ein Hochrisiko-KI-Agent erfordert ein dokumentiertes Risikomanagementsystem über den gesamten Lebenszyklus. Erforderlich sind die Ermittlung, Analyse und Bewertung von Risiken sowie die Umsetzung von Risikomanagementmaßnahmen.","it":"Un agente ad alto rischio richiede un sistema di gestione dei rischi documentato per l''intero ciclo di vita. Sono richieste l''identificazione, l''analisi e la valutazione dei rischi e l''adozione di misure di gestione.","es":"Un agente de alto riesgo requiere un sistema de gestión de riesgos documentado durante todo su ciclo de vida. Se requiere la determinación, el análisis y la evaluación de los riesgos, así como la adopción de medidas de gestión de riesgos.","fr":"Un agent à haut risque requiert un système de gestion des risques documenté tout au long de son cycle de vie. L’identification, l’analyse et l’évaluation des risques ainsi que la mise en œuvre de mesures d’atténuation sont requises.","ro":"Un agent cu grad ridicat de risc necesită un sistem de gestionare a riscurilor documentat pe întreaga durată a ciclului de viață. Sunt necesare identificarea, analiza și evaluarea riscurilor, precum și implementarea măsurilor de atenuare.","ru":"Агент высокого риска требует документированной системы управления рисками на протяжении всего жизненного цикла. Требуются выявление, анализ и оценка рисков, а также внедрение мер по их снижению.","sl":"Visokotvegani agent zahteva dokumentiran sistem obvladovanja tveganja skozi ves življenjski cikel. Zahtevani so prepoznavanje, analiza in ocena tveganj ter uvedba ukrepov za njihovo zmanjšanje.","hr":"Visokorizični agent zahtijeva dokumentirani sustav upravljanja rizikom tijekom cijelog životnog ciklusa. Potrebni su utvrđivanje, analiza i procjena rizika te provedba mjera za njihovo ublažavanje."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'high'::risk_level AND article_ref = 'Art. 9';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Obligation to disclose the use of AI","de":"Pflicht zur Information über KI","it":"Obbligo di informazione sull''IA","es":"Obligación de informar sobre la IA","fr":"Obligation d’information sur l’IA","ro":"Obligația de informare privind IA","ru":"Обязанность информирования об ИИ","sl":"Obveznost obveščanja o UI","hr":"Obveza obavješćivanja o umjetnoj inteligenciji"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"Systems intended to interact with natural persons must inform the user in a clear, distinguishable and timely manner that they are interacting with an automated system, unless this is obvious.","de":"Systeme, die mit natürlichen Personen interagieren, müssen den Nutzer klar, eindeutig und rechtzeitig darüber informieren, dass er mit einem KI-System interagiert, es sei denn, dies ist offensichtlich.","it":"I sistemi destinati a interagire con persone fisiche devono informare l''utente in modo chiaro, distinguibile e tempestivo della natura automatizzata del sistema, a meno che ciò non risulti evidente.","es":"Los sistemas que interactúan con personas físicas deben informar al usuario de manera clara, distinguible y oportuna de que interactúa con un sistema de IA, salvo que resulte evidente.","fr":"Les systèmes destinés à interagir avec des personnes physiques doivent informer l’utilisateur de manière claire, reconnaissable et en temps utile du caractère automatisé du système, sauf si cela ressort clairement du contexte.","ro":"Sistemele care interacționează cu persoane fizice trebuie să informeze utilizatorul în mod clar, distinct și în timp util cu privire la caracterul automatizat al sistemului, cu excepția cazului în care acest lucru este evident.","ru":"Системы, взаимодействующие с людьми, должны информировать пользователя в ясной, понятной и своевременной форме об автоматизированном характере системы, если это не очевидно.","sl":"Sistemi, ki so v interakciji z ljudmi, morajo uporabnika jasno, razločno in pravočasno obvestiti o avtomatizirani naravi sistema, razen če je to očitno.","hr":"Sustavi koji su u interakciji s ljudima moraju korisnika na jasan, razgovijetan i pravodoban način obavijestiti o automatiziranoj prirodi sustava, osim ako je to očito."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'limited'::risk_level AND article_ref = 'Art. 50 ust. 1';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Marking of AI-generated content","de":"Kennzeichnung KI-generierter Inhalte","it":"Marcatura dei contenuti generati dall''IA","es":"Marcado de los contenidos generados por IA","fr":"Marquage des contenus générés par l’IA","ro":"Marcarea conținutului generat de IA","ru":"Маркировка контента, созданного ИИ","sl":"Označevanje vsebin, ustvarjenih z UI","hr":"Označavanje sadržaja generiranog umjetnom inteligencijom"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"AI-generated text, audio and video content must be marked in a machine-readable format as artificially generated.","de":"Von KI erzeugte Text-, Audio- und Videoinhalte müssen in maschinenlesbarem Format als künstlich erzeugt gekennzeichnet sein.","it":"I contenuti testuali, audio e video generati dall''IA devono essere contrassegnati in un formato leggibile meccanicamente come generati dall''IA.","es":"Los contenidos de texto, audio y vídeo generados por IA deben estar marcados en un formato legible por máquina como generados por IA.","fr":"Les contenus textuels, audio et vidéo générés par l’IA doivent être marqués dans un format lisible par machine comme ayant été générés par l’IA.","ro":"Conținutul de tip text, audio și video generat de IA trebuie marcat într-un format care poate fi citit automat ca fiind generat de IA.","ru":"Текстовый, аудио- и видеоконтент, сгенерированный ИИ, должен быть помечен в машиночитаемом формате как созданный ИИ.","sl":"Besedilne, zvočne in video vsebine, ki jih ustvari UI, morajo biti v strojno berljivi obliki označene kot umetno ustvarjene.","hr":"Tekstualni, audio i videosadržaj generiran umjetnom inteligencijom mora biti označen u strojno čitljivom formatu kao umjetno generiran."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'limited'::risk_level AND article_ref = 'Art. 50 ust. 4';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Voluntary codes of conduct","de":"Freiwillige Verhaltenskodizes","it":"Codici di condotta volontari","es":"Códigos de conducta voluntarios","fr":"Codes de conduite volontaires","ro":"Coduri de conduită voluntare","ru":"Добровольные кодексы поведения","sl":"Prostovoljni kodeksi ravnanja","hr":"Dobrovoljni kodeksi ponašanja"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"No mandatory legal requirements apply to minimal-risk systems. The voluntary application of codes of conduct and general principles of trustworthy AI (transparency, fairness, safety) is recommended.","de":"Für KI-Systeme mit minimalem Risiko bestehen keine verpflichtenden rechtlichen Anforderungen. Empfohlen wird die Anwendung freiwilliger Verhaltenskodizes und allgemeiner Grundsätze vertrauenswürdiger KI (Transparenz, Fairness, Sicherheit).","it":"Nessun requisito giuridico obbligatorio per i sistemi a rischio minimo. Si raccomanda l''adozione di codici di condotta volontari e dei principi generali per un''IA affidabile (trasparenza, equità, sicurezza).","es":"No existen requisitos jurídicos obligatorios para los sistemas de riesgo mínimo. Se recomienda aplicar códigos de conducta voluntarios y los principios generales de una IA fiable (transparencia, equidad, seguridad).","fr":"Aucune exigence légale obligatoire pour les systèmes à risque minimal. Il est recommandé d’appliquer des codes de conduite volontaires et les principes généraux d’une IA digne de confiance (transparence, équité, sécurité).","ro":"Nu există cerințe legale obligatorii pentru sistemele cu risc minim. Se recomandă aplicarea codurilor de conduită voluntare și a principiilor generale ale unei IA de încredere (transparență, echitate, siguranță).","ru":"Для систем минимального риска обязательные правовые требования отсутствуют. Рекомендуется применять добровольные кодексы поведения и общие принципы надёжного ИИ (прозрачность, справедливость, безопасность).","sl":"Za sisteme z minimalnim tveganjem ni obveznih pravnih zahtev. Priporočena je uporaba prostovoljnih kodeksov ravnanja in splošnih načel zaupanja vredne UI (preglednost, pravičnost, varnost).","hr":"Za sustave minimalnog rizika ne postoje obvezni pravni zahtjevi. Preporučuje se primjena dobrovoljnih kodeksa ponašanja i općih načela pouzdane umjetne inteligencije (transparentnost, pravednost, sigurnost)."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'minimal'::risk_level AND article_ref = 'Preambuła 46';
UPDATE ai_act_requirements SET title_i18n = '{"en":"Absolute prohibition","de":"Absolutes Verbot","it":"Divieto assoluto di utilizzo","es":"Prohibición absoluta","fr":"Interdiction absolue","ro":"Interdicție absolută de utilizare","ru":"Безусловный запрет применения","sl":"Absolutna prepoved uporabe","hr":"Bezuvjetna zabrana upotrebe"}'::jsonb || COALESCE(title_i18n, '{}'::jsonb),
    text_i18n = '{"en":"The AI practices listed in Art. 5 are strictly prohibited in the EU. It must be verified that the system does not fall into any of the prohibited categories (subliminal manipulation, social scoring, real-time biometric identification).","de":"Die in Art. 5 genannten KI-Praktiken sind in der EU ausnahmslos verboten. Es ist zu prüfen, ob das System unter eine der verbotenen Kategorien fällt (unterschwellige Beeinflussung, Social Scoring, biometrische Echtzeit-Fernidentifizierung).","it":"Le pratiche di IA elencate all''art. 5 sono tassativamente vietate nell''UE. È necessario verificare che il sistema non rientri in alcuna delle categorie vietate (manipolazione subliminale, social scoring, identificazione biometrica in tempo reale).","es":"Las prácticas de IA enumeradas en el art. 5 están terminantemente prohibidas en la UE. Se requiere verificar que el sistema no se encuadra en ninguna de las categorías prohibidas (manipulación subliminal, puntuación ciudadana, identificación biométrica remota en tiempo real).","fr":"Les pratiques en matière d’IA énumérées à l’art. 5 sont strictement interdites dans l’UE. Il convient de vérifier que le système ne relève d’aucune des catégories interdites (manipulation subliminale, notation sociale, identification biométrique en temps réel).","ro":"Practicile în domeniul IA enumerate la art. 5 sunt interzise în mod absolut în UE. Este necesară verificarea faptului că sistemul nu se încadrează în niciuna dintre categoriile interzise (manipulare subliminală, evaluarea comportamentului social, identificare biometrică în timp real).","ru":"Практики ИИ, перечисленные в ст. 5, безусловно запрещены в ЕС. Требуется проверка того, что система не подпадает ни под одну из запрещённых категорий (подсознательное манипулирование, социальный скоринг, биометрическая идентификация в режиме реального времени).","sl":"Prakse UI iz člena 5 so v EU absolutno prepovedane. Treba je preveriti, da sistem ne spada v nobeno od prepovedanih kategorij (subliminalna manipulacija, družbeno točkovanje, biometrična identifikacija v realnem času).","hr":"Prakse umjetne inteligencije navedene u članku 5. u EU-u su bezuvjetno zabranjene. Potrebno je provjeriti da sustav ne pripada nijednoj od zabranjenih kategorija (subliminalna manipulacija, društveno vrednovanje, biometrijska identifikacija u stvarnom vremenu)."}'::jsonb || COALESCE(text_i18n, '{}'::jsonb)
  WHERE risk_level = 'unacceptable'::risk_level AND article_ref = 'Art. 5';

