    unit_i18n = '{"en":"EUR","de":"EUR","it":"EUR","es":"EUR","fr":"EUR","ro":"EUR","ru":"EUR","sl":"EUR","hr":"EUR"}'::jsonb || COALESCE(unit_i18n, '{}'::jsonb)
  WHERE key = 'budget.default_monthly_eur';
UPDATE app_settings SET label_i18n = '{"en":"Compliance gap deadlines (days)","de":"Fristen für Compliance-Lücken (Tage)","it":"Scadenze delle lacune di compliance (giorni)","es":"Plazos de las carencias de cumplimiento (días)","fr":"Échéances des lacunes de conformité (jours)","ro":"Termene pentru lacunele de conformitate (zile)","ru":"Сроки устранения пробелов (дни)","sl":"Roki za vrzeli v skladnosti (dni)","hr":"Rokovi za nedostatke u usklađenosti (dani)"}'::jsonb || COALESCE(label_i18n, '{}'::jsonb),
    description_i18n = '{"en":"Number of days to remedy individual high-risk compliance gaps (key = control field).","de":"Anzahl der Tage zur Behebung einzelner Konformitätslücken bei hohem Risiko (Schlüssel = Kontrollfeld).","it":"Numero di giorni per colmare le singole lacune di conformità dei sistemi ad alto rischio (chiave = campo di controllo).","es":"Número de días para subsanar cada carencia de cumplimiento de alto riesgo (clave = campo de control).","fr":"Nombre de jours pour combler chacune des lacunes de conformité à haut risque (clé = champ de contrôle).","ro":"Numărul de zile pentru remedierea fiecărei lacune de conformitate pentru sistemele cu risc ridicat (cheie = câmp de control).","ru":"Количество дней на устранение отдельных пробелов в соответствии для систем высокого риска (ключ = контрольное поле).","sl":"Število dni za odpravo posameznih vrzeli v skladnosti pri visokem tveganju (ključ = polje kontrole).","hr":"Broj dana za otklanjanje pojedinih nedostataka u usklađenosti visokorizičnih sustava (ključ = kontrolno polje)."}'::jsonb || COALESCE(description_i18n, '{}'::jsonb),
    unit_i18n = '{"en":"days","de":"Tage","it":"giorni","es":"días","fr":"jours","ro":"zile","ru":"дни","sl":"dni","hr":"dani"}'::jsonb || COALESCE(unit_i18n, '{}'::jsonb)
