UPDATE app_settings SET label_i18n = '{"en":"Default language","de":"Standardsprache","it":"Lingua predefinita","es":"Idioma predeterminado","fr":"Langue par défaut","ro":"Limba implicită","ru":"Язык по умолчанию","sl":"Privzeti jezik","hr":"Zadani jezik"}'::jsonb || COALESCE(label_i18n, '{}'::jsonb),
    description_i18n = '{"en":"Language of the interface, reports and messages for users who have not chosen their own. Codes: pl, en, de, it, es, fr, ro, ru, sl, hr.","de":"Sprache der Benutzeroberfläche, der Berichte und der Meldungen für Benutzer, die keine eigene Sprache gewählt haben. Codes: pl, en, de, it, es, fr, ro, ru, sl, hr.","it":"Lingua dell''interfaccia, dei report e dei messaggi per gli utenti che non ne hanno scelta una propria. Codici: pl, en, de, it, es, fr, ro, ru, sl, hr.","es":"Idioma de la interfaz, los informes y los mensajes para los usuarios que no han elegido uno propio. Códigos: pl, en, de, it, es, fr, ro, ru, sl, hr.","fr":"Langue de l’interface, des rapports et des messages pour les utilisateurs n’ayant pas choisi leur propre langue. Codes : pl, en, de, it, es, fr, ro, ru, sl, hr.","ro":"Limba interfeței, a rapoartelor și a mesajelor pentru utilizatorii care nu și-au ales propria limbă. Coduri: pl, en, de, it, es, fr, ro, ru, sl, hr.","ru":"Язык интерфейса, отчётов и сообщений для пользователей, не выбравших собственный язык. Коды: pl, en, de, it, es, fr, ro, ru, sl, hr.","sl":"Jezik vmesnika, poročil in sporočil za uporabnike, ki niso izbrali svojega. Kode: pl, en, de, it, es, fr, ro, ru, sl, hr.","hr":"Jezik sučelja, izvješća i poruka za korisnike koji nisu odabrali vlastiti jezik. Kodovi: pl, en, de, it, es, fr, ro, ru, sl, hr."}'::jsonb || COALESCE(description_i18n, '{}'::jsonb)
  WHERE key = 'i18n.default_locale';
UPDATE app_settings SET label_i18n = '{"en":"Policy refresh","de":"Neuladen der Richtlinien","it":"Aggiornamento delle policy","es":"Recarga de políticas","fr":"Rechargement des politiques","ro":"Reîncărcarea politicilor","ru":"Обновление политик","sl":"Osveževanje pravilnikov","hr":"Osvježavanje pravila"}'::jsonb || COALESCE(label_i18n, '{}'::jsonb),
    description_i18n = '{"en":"How often (in seconds) the gateway reloads policy rules from the database.","de":"In welchem Sekundenabstand das Gateway die Richtlinienregeln aus der Datenbank neu lädt.","it":"Ogni quanti secondi il gateway ricarica dal database le regole delle policy.","es":"Cada cuántos segundos la pasarela recarga las reglas de las políticas desde la base de datos.","fr":"Intervalle en secondes auquel la passerelle recharge les règles des politiques depuis la base de données.","ro":"La câte secunde gateway-ul reîncarcă regulile politicilor din baza de date.","ru":"Интервал в секундах, с которым шлюз перезагружает правила политик из базы данных.","sl":"Na koliko sekund varnostni prehod znova naloži pravila pravilnikov iz baze.","hr":"Svakih koliko sekundi gateway ponovno učitava sigurnosna pravila iz baze."}'::jsonb || COALESCE(description_i18n, '{}'::jsonb),
    unit_i18n = '{"en":"seconds","de":"Sekunden","it":"secondi","es":"segundos","fr":"secondes","ro":"secunde","ru":"секунды","sl":"sekunde","hr":"sekunde"}'::jsonb || COALESCE(unit_i18n, '{}'::jsonb)
