    description_i18n = '{"en":"Minimum Presidio confidence level for a PII detection to be accepted.","de":"Minimale Konfidenz von Presidio, ab der eine Erkennung personenbezogener Daten anerkannt wird.","it":"Livello minimo di confidenza di Presidio per considerare valido un rilevamento di dati personali.","es":"Nivel mínimo de confianza de Presidio para considerar válida una detección de datos personales.","fr":"Niveau de confiance minimal de Presidio pour retenir une détection de DCP.","ro":"Nivelul minim de încredere Presidio pentru ca o detectare de date personale să fie validată.","ru":"Минимальный уровень уверенности Presidio для признания выявления ПДн.","sl":"Najmanjša stopnja zanesljivosti Presidio, da se zaznava PII upošteva.","hr":"Najmanja razina pouzdanosti Presidija za prihvaćanje otkrivanja osobnih podataka."}'::jsonb || COALESCE(description_i18n, '{}'::jsonb),
    unit_i18n = '{"en":"0–1","de":"0–1","it":"0–1","es":"0–1","fr":"0–1","ro":"0–1","ru":"0–1","sl":"0–1","hr":"0–1"}'::jsonb || COALESCE(unit_i18n, '{}'::jsonb)
  WHERE key = 'security.pii_confidence_threshold';
