UPDATE providers SET notes_i18n = '{"en":"External provider. Requires a DPA. Do not use for data covered by legal professional privilege.","de":"Externer Modellanbieter. Erfordert einen AVV (DPA). Nicht für Daten verwenden, die dem Anwaltsgeheimnis unterliegen.","it":"Provider esterno. Richiede un DPA. Non utilizzare per dati coperti dal segreto professionale forense.","es":"Proveedor externo. Requiere un acuerdo de encargo del tratamiento (DPA). No utilizar para datos amparados por el secreto profesional del abogado.","fr":"Fournisseur externe. Nécessite un DPA. Ne pas utiliser pour des données couvertes par le secret professionnel de l’avocat.","ro":"Furnizor extern de modele. Necesită DPA. A nu se utiliza pentru date protejate de secretul profesional al avocatului.","ru":"Внешний поставщик моделей. Требуется DPA. Не использовать для данных, составляющих адвокатскую тайну.","sl":"Zunanji dobavitelj. Zahteva DPA. Ne uporabljajte za podatke, zaščitene z odvetniško tajnostjo.","hr":"Vanjski pružatelj. Zahtijeva DPA. Ne upotrebljavati za podatke obuhvaćene odvjetničkom tajnom."}'::jsonb || COALESCE(notes_i18n, '{}'::jsonb)
