UPDATE providers SET notes_i18n = '{"en":"Local model — suitable for data covered by legal professional privilege. Activate once the Ollama server is running.","de":"Lokales Modell — für Daten unter Anwaltsgeheimnis geeignet. Nach dem Start des Ollama-Servers aktivieren.","it":"Modello locale — idoneo per il segreto professionale forense. Attivare dopo l''avvio del server Ollama.","es":"Modelo local — apto para datos amparados por el secreto profesional del abogado. Actívelo tras iniciar el servidor Ollama.","fr":"Modèle local — compatible avec le secret professionnel de l’avocat. À activer après le démarrage du serveur Ollama.","ro":"Model local — compatibil cu secretul profesional al avocatului. Activați după pornirea serverului Ollama.","ru":"Локальная модель — допустима для данных, составляющих адвокатскую тайну. Активируйте после запуска сервера Ollama.","sl":"Lokalni model — primeren za podatke pod odvetniško tajnostjo. Aktivirajte ga po zagonu strežnika Ollama.","hr":"Lokalni model — prikladan za podatke obuhvaćene odvjetničkom tajnom. Aktivirajte nakon pokretanja poslužitelja Ollama."}'::jsonb || COALESCE(notes_i18n, '{}'::jsonb)
  WHERE name = 'Bielik On-Prem (Local)';
UPDATE providers SET notes_i18n = '{"en":"Servers outside the EU (China). Public data only — processing of client data is prohibited.","de":"Server außerhalb der EU (China). Ausschließlich öffentliche Daten — Verarbeitung von Kundendaten untersagt.","it":"Server fuori dall''UE (Cina). Esclusivamente dati pubblici — divieto di trattamento dei dati dei clienti.","es":"Servidores fuera de la UE (China). Exclusivamente datos públicos — prohibido el tratamiento de datos de clientes.","fr":"Serveurs hors UE (Chine). Données publiques uniquement — traitement des données clients interdit.","ro":"Servere în afara UE (China). Exclusiv date publice — prelucrarea datelor clienților este interzisă.","ru":"Серверы за пределами ЕС (Китай). Только публичные данные — обработка данных клиентов запрещена.","sl":"Strežniki zunaj EU (Kitajska). Izključno javni podatki — obdelava podatkov strank je prepovedana.","hr":"Poslužitelji izvan EU-a (Kina). Isključivo javni podaci — obrada podataka klijenata je zabranjena."}'::jsonb || COALESCE(notes_i18n, '{}'::jsonb)
