UPDATE providers SET notes_i18n = '{"en":"External provider with EU Data Boundary. Requires a DPA. Do not use for privileged data.","de":"Externer Modellanbieter mit EU Data Boundary. Erfordert einen AVV (DPA). Nicht für privilegierte Daten verwenden.","it":"Provider esterno con EU Data Boundary. Richiede un DPA. Non utilizzare per dati privilegiati.","es":"Proveedor externo con EU Data Boundary. Requiere un acuerdo de encargo del tratamiento (DPA). No utilizar para datos privilegiados.","fr":"Fournisseur externe avec EU Data Boundary. Nécessite un DPA. Ne pas utiliser pour des données privilégiées.","ro":"Furnizor extern de modele cu EU Data Boundary. Necesită DPA. A nu se utiliza pentru date privilegiate.","ru":"Внешний поставщик моделей с EU Data Boundary. Требуется DPA. Не использовать для привилегированных данных.","sl":"Zunanji dobavitelj z EU Data Boundary. Zahteva DPA. Ne uporabljajte za privilegirane podatke.","hr":"Vanjski pružatelj s EU Data Boundary. Zahtijeva DPA. Ne upotrebljavati za povlaštene podatke."}'::jsonb || COALESCE(notes_i18n, '{}'::jsonb)
